import{_ as a,o as l,c as i,a3 as r}from"./chunks/framework.Bh_aNVBG.js";const e="/images/super-admin/image-87.png",c=JSON.parse('{"title":"9. 안내 페이지 공개 및 운영","description":"","frontmatter":{},"headers":[],"relativePath":"publishing.md","filePath":"publishing.md"}'),o={name:"publishing.md"};function d(h,t,n,s,p,u){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_9-안내-페이지-공개-및-운영" tabindex="-1">9. 안내 페이지 공개 및 운영 <a class="header-anchor" href="#_9-안내-페이지-공개-및-운영" aria-label="Permalink to &quot;9. 안내 페이지 공개 및 운영&quot;">​</a></h1><p>프로젝트의 기본 설정과 콘텐츠 등록이 완료되면 방문객에게 안내 페이지를 공개하고 운영할 수 있습니다.</p><p>프로젝트 운영자는 CMS에서 프로젝트 상태를 관리하고, 행사 운영 중 콘텐츠와 공지사항을 수정하여 방문객에게 최신 정보를 제공할 수 있습니다.</p><p>본 장에서는 안내 페이지 공개 전 점검, 프로젝트 상태 관리, 안내 페이지 접속 및 행사 운영 중 콘텐츠 관리 방법을 안내합니다.</p><h2 id="_9-1-안내-페이지-공개-전-확인사항" tabindex="-1">9.1. 안내 페이지 공개 전 확인사항 <a class="header-anchor" href="#_9-1-안내-페이지-공개-전-확인사항" aria-label="Permalink to &quot;9.1. 안내 페이지 공개 전 확인사항&quot;">​</a></h2><p>안내 페이지를 공개하기 전에는 프로젝트의 기본 설정과 주요 콘텐츠가 정상적으로 등록되어 있는지 확인해야 합니다.</p><h3 id="_1-프로젝트-기본-설정-확인" tabindex="-1">① 프로젝트 기본 설정 확인 <a class="header-anchor" href="#_1-프로젝트-기본-설정-확인" aria-label="Permalink to &quot;① 프로젝트 기본 설정 확인&quot;">​</a></h3><p><strong>프로젝트 설정</strong> 메뉴에서 다음 항목을 확인합니다.</p><table tabindex="0"><thead><tr><th>확인 항목</th><th>확인 내용</th></tr></thead><tbody><tr><td>프로젝트 기본 정보</td><td>행사명, 행사 기간 및 담당자 정보</td></tr><tr><td>브랜딩</td><td>로고, 대표 색상, 강조 색상 및 글꼴</td></tr><tr><td>다국어</td><td>기본 언어 및 지원 언어</td></tr><tr><td>서비스 모듈</td><td>사용할 기능의 활성화 상태</td></tr><tr><td>하단 내비게이션</td><td>메뉴 구성, 순서 및 최초 진입 화면</td></tr></tbody></table><h3 id="_2-콘텐츠-등록-상태-확인" tabindex="-1">② 콘텐츠 등록 상태 확인 <a class="header-anchor" href="#_2-콘텐츠-등록-상태-확인" aria-label="Permalink to &quot;② 콘텐츠 등록 상태 확인&quot;">​</a></h3><p>다음 항목 중 프로젝트에서 사용하는 기능의 콘텐츠가 준비되었는지 확인합니다.</p><ul><li>메인 배너, 하이라이트, 바로가기 및 하단 푸터</li><li>상세 콘텐츠 및 행사 일정</li><li>투어맵 기본 설정 및 지도 객체</li><li>스탬프 투어 코스 및 수집 지점</li><li>AI 챗봇, 설문조사, 오디오·비디오 가이드</li><li>공지사항</li></ul><blockquote><p><strong>참고</strong></p><p>모든 서비스 기능을 반드시 사용할 필요는 없습니다. 프로젝트에서 활성화한 기능을 중심으로 점검해 주세요.</p></blockquote><hr><h2 id="_9-2-프로젝트-상태-관리" tabindex="-1">9.2. 프로젝트 상태 관리 <a class="header-anchor" href="#_9-2-프로젝트-상태-관리" aria-label="Permalink to &quot;9.2. 프로젝트 상태 관리&quot;">​</a></h2><p>프로젝트 상태는 방문객에게 안내 페이지를 제공할지 결정하는 설정입니다.</p><p>프로젝트 운영자는 행사 준비, 운영 및 종료 상황에 따라 프로젝트 상태를 변경할 수 있습니다.</p><h3 id="_1-프로젝트-상태-안내" tabindex="-1">① 프로젝트 상태 안내 <a class="header-anchor" href="#_1-프로젝트-상태-안내" aria-label="Permalink to &quot;① 프로젝트 상태 안내&quot;">​</a></h3><table tabindex="0"><thead><tr><th>상태</th><th>설명</th><th>방문객 화면</th></tr></thead><tbody><tr><td>준비중</td><td>프로젝트 준비 단계</td><td>준비중 안내 페이지 표시</td></tr><tr><td>활성화</td><td>안내 페이지 운영 단계</td><td>정상 안내 페이지 표시</td></tr><tr><td>비활성화</td><td>프로젝트 운영 중단 또는 종료</td><td>안내 페이지 미표시</td></tr></tbody></table><p><strong>준비중</strong></p><p>프로젝트의 콘텐츠를 등록하거나 서비스를 구성하는 단계에서 사용합니다.</p><p>방문객이 안내 페이지 주소로 접속하면 일반 안내 페이지 대신 <strong>준비중 안내 화면</strong>이 표시됩니다.</p><p><strong>활성화</strong></p><p>행사 안내 페이지의 구성이 완료되어 방문객에게 서비스를 제공할 때 사용합니다.</p><p>방문객은 홈, 투어맵, 일정 등 프로젝트에 설정된 기능을 정상적으로 이용할 수 있습니다.</p><p><strong>비활성화</strong></p><p>프로젝트 운영을 중단하거나 종료할 때 사용합니다.</p><p>방문객이 안내 페이지 주소로 접속하더라도 행사 안내 페이지가 제공되지 않습니다.</p><h3 id="_2-프로젝트-상태-변경-방법" tabindex="-1">② 프로젝트 상태 변경 방법 <a class="header-anchor" href="#_2-프로젝트-상태-변경-방법" aria-label="Permalink to &quot;② 프로젝트 상태 변경 방법&quot;">​</a></h3><ol><li>CMS에서 관리할 프로젝트를 선택합니다.</li><li><strong>프로젝트 설정 &gt; 기본 정보</strong> 메뉴로 이동합니다.</li><li><strong>상태</strong> 항목에서 원하는 상태를 선택합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li><li>변경된 상태가 정상적으로 적용되었는지 확인합니다.</li></ol><p><img src="'+e+'" alt="image.png"></p><h3 id="_3-프로젝트-상태별-화면-확인" tabindex="-1">③ 프로젝트 상태별 화면 확인 <a class="header-anchor" href="#_3-프로젝트-상태별-화면-확인" aria-label="Permalink to &quot;③ 프로젝트 상태별 화면 확인&quot;">​</a></h3><p>프로젝트 상태를 변경한 후에는 방문객용 안내 페이지에 접속하여 실제 표시 상태를 확인합니다.</p><blockquote><p><strong>주의사항</strong></p><p>프로젝트를 <strong>비활성화</strong>하면 방문객에게 안내 페이지가 제공되지 않습니다.</p><p>행사 운영 중 실수로 비활성화하지 않도록 주의해 주세요. 행사 종료 후에도 방문객에게 정보를 제공해야 하는 경우에는 공개 유지 여부를 검토한 후 상태를 변경해 주세요.</p></blockquote><h3 id="_4-프로젝트-상태-활용-예시" tabindex="-1">④ 프로젝트 상태 활용 예시 <a class="header-anchor" href="#_4-프로젝트-상태-활용-예시" aria-label="Permalink to &quot;④ 프로젝트 상태 활용 예시&quot;">​</a></h3><table tabindex="0"><thead><tr><th>운영 단계</th><th>권장 상태</th></tr></thead><tbody><tr><td>프로젝트 최초 설정 및 콘텐츠 등록</td><td>준비중</td></tr><tr><td>행사 안내 페이지 공개</td><td>활성화</td></tr><tr><td>행사 진행 중</td><td>활성화</td></tr><tr><td>행사 종료 후 안내 페이지 유지</td><td>활성화</td></tr><tr><td>안내 페이지 서비스 종료</td><td>비활성화</td></tr></tbody></table><blockquote><p><strong>참고</strong></p><p>프로젝트가 준비중 또는 비활성화 상태여도 관리자 권한이 있는 사용자는 CMS에서 프로젝트의 콘텐츠와 설정을 관리할 수 있습니다.</p></blockquote><hr><h2 id="_9-3-안내-페이지-접속-및-공유" tabindex="-1">9.3. 안내 페이지 접속 및 공유 <a class="header-anchor" href="#_9-3-안내-페이지-접속-및-공유" aria-label="Permalink to &quot;9.3. 안내 페이지 접속 및 공유&quot;">​</a></h2><p>프로젝트가 활성화되면 해당 프로젝트의 URL을 이용하여 방문객용 안내 페이지에 접속할 수 있습니다.</p><h3 id="_1-안내-페이지-url-확인" tabindex="-1">① 안내 페이지 URL 확인 <a class="header-anchor" href="#_1-안내-페이지-url-확인" aria-label="Permalink to &quot;① 안내 페이지 URL 확인&quot;">​</a></h3><ol><li>CMS의 <strong>프로젝트 관리</strong> 화면으로 이동합니다.</li><li>공개한 프로젝트를 찾습니다.</li><li>상태가 <strong>활성화</strong>인지 확인합니다.</li><li>프로젝트 목록의 <strong>URL</strong> 항목에 있는 이동 버튼을 클릭합니다.</li><li>새 브라우저 탭에서 방문객용 안내 페이지가 열리는지 확인합니다.</li></ol><h3 id="_2-안내-페이지-주소" tabindex="-1">② 안내 페이지 주소 <a class="header-anchor" href="#_2-안내-페이지-주소" aria-label="Permalink to &quot;② 안내 페이지 주소&quot;">​</a></h3><p>프로젝트의 안내 페이지 주소는 프로젝트별 URL Slug를 기준으로 구성됩니다.</p><p><strong>주소 형식</strong></p><p><code>https://{프로젝트 슬러그}.infodio.kr</code></p><p>예를 들어 슬러그가 <code>sample-festival</code>이면 안내 페이지 주소는 다음과 같습니다.</p><p><code>https://sample-festival.infodio.kr</code></p><p>※ 위 주소는 형식을 설명하기 위한 예시입니다.</p><h3 id="_3-방문객에게-안내-페이지-공유" tabindex="-1">③ 방문객에게 안내 페이지 공유 <a class="header-anchor" href="#_3-방문객에게-안내-페이지-공유" aria-label="Permalink to &quot;③ 방문객에게 안내 페이지 공유&quot;">​</a></h3><p>확인한 안내 페이지 URL은 행사 홍보물 등에서 공유할 수 있습니다.</p><p><strong>활용 예시</strong></p><ul><li>행사 공식 홈페이지</li><li>SNS 및 온라인 홍보 게시물</li><li>행사장 안내 배너</li><li>리플릿 및 인쇄 홍보물</li><li>QR 코드 안내판</li></ul><p>URL을 공유하기 전에 모바일에서 정상적으로 접속되는지 확인해 주세요.</p><hr><h2 id="_9-4-방문객용-안내-페이지-최종-점검" tabindex="-1">9.4. 방문객용 안내 페이지 최종 점검 <a class="header-anchor" href="#_9-4-방문객용-안내-페이지-최종-점검" aria-label="Permalink to &quot;9.4. 방문객용 안내 페이지 최종 점검&quot;">​</a></h2><p>안내 페이지를 활성화한 후에는 실제 방문객이 사용하는 환경에서 주요 기능을 점검합니다.</p><h3 id="_1-홈-화면-확인" tabindex="-1">① 홈 화면 확인 <a class="header-anchor" href="#_1-홈-화면-확인" aria-label="Permalink to &quot;① 홈 화면 확인&quot;">​</a></h3><ol><li>안내 페이지에 접속합니다.</li><li>메인 배너와 주요 콘텐츠가 정상적으로 표시되는지 확인합니다.</li><li>바로가기와 하단 내비게이션 메뉴를 선택합니다.</li><li>각 메뉴가 올바른 페이지로 이동하는지 확인합니다.</li></ol><h3 id="_2-행사-콘텐츠-확인" tabindex="-1">② 행사 콘텐츠 확인 <a class="header-anchor" href="#_2-행사-콘텐츠-확인" aria-label="Permalink to &quot;② 행사 콘텐츠 확인&quot;">​</a></h3><ul><li>상세 콘텐츠의 제목과 본문 확인</li><li>이미지 및 영상 표시 확인</li><li>행사 일정과 운영 시간 확인</li><li>카테고리 및 배지 확인</li><li>공지사항 내용 확인</li></ul><h3 id="_3-지도-및-참여형-서비스-확인" tabindex="-1">③ 지도 및 참여형 서비스 확인 <a class="header-anchor" href="#_3-지도-및-참여형-서비스-확인" aria-label="Permalink to &quot;③ 지도 및 참여형 서비스 확인&quot;">​</a></h3><ul><li>투어맵의 초기 위치와 지도 객체 표시 확인</li><li>마커 선택 및 바텀시트 동작 확인</li><li>스탬프 투어 코스와 수집 지점 확인</li><li>설문조사 및 부가 서비스 동작 확인</li></ul><h3 id="_4-모바일-환경-점검" tabindex="-1">④ 모바일 환경 점검 <a class="header-anchor" href="#_4-모바일-환경-점검" aria-label="Permalink to &quot;④ 모바일 환경 점검&quot;">​</a></h3><p>방문객은 주로 모바일 기기를 이용하므로 모바일 환경에서의 확인이 중요합니다.</p><p>특히 다음 내용을 점검합니다.</p><ul><li>화면 너비에 맞게 콘텐츠가 표시되는지</li><li>이미지와 텍스트가 잘리지 않는지</li><li>버튼과 메뉴가 정상적으로 동작하는지</li><li>하단 내비게이션이 올바르게 표시되는지</li><li>언어 변경 시 콘텐츠가 정상적으로 제공되는지</li></ul><hr><h2 id="_9-5-운영-중-콘텐츠-수정" tabindex="-1">9.5. 운영 중 콘텐츠 수정 <a class="header-anchor" href="#_9-5-운영-중-콘텐츠-수정" aria-label="Permalink to &quot;9.5. 운영 중 콘텐츠 수정&quot;">​</a></h2><p>행사 운영 중 일정이나 장소 정보 등이 변경되면 CMS에서 해당 내용을 수정할 수 있습니다.</p><h3 id="_1-콘텐츠-수정-방법" tabindex="-1">① 콘텐츠 수정 방법 <a class="header-anchor" href="#_1-콘텐츠-수정-방법" aria-label="Permalink to &quot;① 콘텐츠 수정 방법&quot;">​</a></h3><ol><li>CMS에 로그인합니다.</li><li>수정할 프로젝트의 관리 화면으로 이동합니다.</li><li>변경할 콘텐츠의 관리 메뉴를 선택합니다.</li><li>기존 내용을 수정합니다.</li><li><strong>저장</strong> 버튼을 클릭합니다.</li><li>방문객용 안내 페이지에서 변경된 내용을 확인합니다.</li></ol><h3 id="_2-운영-중-주요-수정-항목" tabindex="-1">② 운영 중 주요 수정 항목 <a class="header-anchor" href="#_2-운영-중-주요-수정-항목" aria-label="Permalink to &quot;② 운영 중 주요 수정 항목&quot;">​</a></h3><table tabindex="0"><thead><tr><th>수정 항목</th><th>활용 상황</th></tr></thead><tbody><tr><td>행사 일정</td><td>공연 시간 변경, 프로그램 취소</td></tr><tr><td>상세 콘텐츠</td><td>운영 정보 및 안내 문구 변경</td></tr><tr><td>투어맵</td><td>시설 위치 변경, 임시 통제 구역 반영</td></tr><tr><td>공지사항</td><td>긴급 안내, 교통 통제, 운영 변경</td></tr><tr><td>메인 배너</td><td>주요 홍보 내용 변경</td></tr><tr><td>스탬프 투어</td><td>수집 지점 및 운영 조건 점검</td></tr></tbody></table><blockquote><p><strong>주의사항</strong></p><p>운영 중인 콘텐츠를 수정하면 방문객이 확인하는 정보에도 영향을 줄 수 있습니다.</p><p>중요한 내용을 변경한 경우 저장 후 실제 안내 페이지에서 정상적으로 표시되는지 확인해 주세요.</p></blockquote><hr><h2 id="_9-6-공지사항을-통한-운영-정보-안내" tabindex="-1">9.6. 공지사항을 통한 운영 정보 안내 <a class="header-anchor" href="#_9-6-공지사항을-통한-운영-정보-안내" aria-label="Permalink to &quot;9.6. 공지사항을 통한 운영 정보 안내&quot;">​</a></h2><p>행사 운영 중 발생하는 주요 변경 사항은 공지사항을 통해 방문객에게 안내할 수 있습니다.</p><h3 id="_1-공지사항-등록" tabindex="-1">① 공지사항 등록 <a class="header-anchor" href="#_1-공지사항-등록" aria-label="Permalink to &quot;① 공지사항 등록&quot;">​</a></h3><ol><li><strong>공지사항</strong> 메뉴로 이동합니다.</li><li>안내할 내용을 입력합니다.</li><li><strong>추가</strong> 버튼을 클릭합니다.</li><li>현재 노출 중인 공지사항 목록을 확인합니다.</li></ol><h3 id="_2-운영-중-공지사항-활용-예시" tabindex="-1">② 운영 중 공지사항 활용 예시 <a class="header-anchor" href="#_2-운영-중-공지사항-활용-예시" aria-label="Permalink to &quot;② 운영 중 공지사항 활용 예시&quot;">​</a></h3><table tabindex="0"><thead><tr><th>상황</th><th>공지사항 예시</th></tr></thead><tbody><tr><td>공연 시간 변경</td><td>현장 상황으로 인해 메인 공연이 오후 4시부터 진행됩니다.</td></tr><tr><td>시설 이용 제한</td><td>안전 점검으로 인해 동측 출입구 이용이 일시 제한됩니다.</td></tr><tr><td>교통 안내</td><td>행사장 주변 교통 혼잡이 예상되오니 대중교통을 이용해 주세요.</td></tr><tr><td>운영 종료</td><td>금일 체험 프로그램 접수가 마감되었습니다.</td></tr></tbody></table><h3 id="_3-공지사항-노출-종료" tabindex="-1">③ 공지사항 노출 종료 <a class="header-anchor" href="#_3-공지사항-노출-종료" aria-label="Permalink to &quot;③ 공지사항 노출 종료&quot;">​</a></h3><p>안내가 더 이상 필요하지 않은 경우 해당 공지사항의 노출을 종료할 수 있습니다.</p><p>노출을 종료한 공지사항은 이력으로 보관되며 필요한 경우 다시 노출할 수 있습니다.</p><p>자세한 내용은 <strong>5.5. 공지사항 등록 및 관리</strong>를 참고해 주세요.</p><hr><h2 id="_9-7-행사-종료-후-프로젝트-관리" tabindex="-1">9.7. 행사 종료 후 프로젝트 관리 <a class="header-anchor" href="#_9-7-행사-종료-후-프로젝트-관리" aria-label="Permalink to &quot;9.7. 행사 종료 후 프로젝트 관리&quot;">​</a></h2><p>행사가 종료된 후에는 프로젝트 상태와 주요 콘텐츠를 확인하여 안내 페이지를 정리할 수 있습니다.</p><h3 id="_1-행사-종료-후-확인사항" tabindex="-1">① 행사 종료 후 확인사항 <a class="header-anchor" href="#_1-행사-종료-후-확인사항" aria-label="Permalink to &quot;① 행사 종료 후 확인사항&quot;">​</a></h3><ul><li>행사 일정 및 프로그램 운영 종료 여부</li><li>노출 중인 공지사항</li><li>스탬프 투어 및 보상 운영 종료 여부</li><li>설문조사 운영 기간</li><li>안내 페이지 운영 유지 여부</li></ul><h3 id="_2-프로젝트-비활성화" tabindex="-1">② 프로젝트 비활성화 <a class="header-anchor" href="#_2-프로젝트-비활성화" aria-label="Permalink to &quot;② 프로젝트 비활성화&quot;">​</a></h3><p>방문객용 안내 페이지 운영을 종료할 경우 프로젝트를 비활성화할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>프로젝트 관리 화면으로 이동합니다.</li><li><strong>프로젝트 설정 &gt; 기본 정보</strong>를 선택합니다.</li><li>프로젝트 상태를 <strong>비활성화</strong>로 변경합니다.</li><li>변경 내용을 저장합니다.</li><li>방문객용 안내 페이지의 접속 상태를 확인합니다.</li></ol><blockquote><p><strong>주의사항</strong></p><p>프로젝트 비활성화는 방문객의 서비스 이용에 영향을 줄 수 있습니다.</p><p>행사 종료 후에도 일정 기간 정보를 제공해야 하는 경우 운영 종료 일정과 공개 유지 여부를 확인한 후 변경해 주세요.</p></blockquote><hr><h2 id="_9-8-운영-전-최종-체크리스트" tabindex="-1">9.8. 운영 전 최종 체크리스트 <a class="header-anchor" href="#_9-8-운영-전-최종-체크리스트" aria-label="Permalink to &quot;9.8. 운영 전 최종 체크리스트&quot;">​</a></h2><p>프로젝트를 방문객에게 공개하기 전에 아래 항목을 최종 점검해 주세요.</p><p><strong>프로젝트 설정</strong></p><ul><li>프로젝트 기본 정보 및 운영 기간 확인</li><li>프로젝트 상태 확인</li><li>로고, 색상 및 글꼴 확인</li><li>지원 언어 및 서비스 모듈 확인</li><li>하단 내비게이션 및 최초 진입 화면 확인</li></ul><p><strong>콘텐츠 및 서비스</strong></p><ul><li>메인 배너 및 바로가기 링크 확인</li><li>상세 콘텐츠 및 행사 일정 확인</li><li>투어맵 및 지도 객체 표시 확인</li><li>스탬프 투어와 보상 정책 확인</li><li>AI 챗봇 및 부가 서비스 동작 확인</li><li>공지사항 확인</li></ul><p><strong>방문객 화면</strong></p><ul><li>안내 페이지 URL 접속 확인</li><li>모바일 화면 표시 확인</li><li>주요 버튼과 연결 링크 확인</li><li>다국어 콘텐츠 표시 확인</li><li>실제 행사 운영 정보와 일치하는지 확인</li></ul><blockquote><p><strong>참고</strong></p><p>행사 시작 직전에는 안내 페이지를 실제 모바일 기기에서 확인하는 것을 권장합니다.</p><p>특히 일정, 장소, 이용 시간 등 현장 운영과 직접 관련된 정보는 반드시 최신 상태로 유지해 주세요.</p></blockquote>',106)])])}const _=a(o,[["render",d]]);export{c as __pageData,_ as default};
